func TestParseBIFF8TagSource(t *testing.T) {
	// StdEncoding ignores \r\n, so the multi-line fixture decodes directly.
	data, err := base64.StdEncoding.DecodeString(tagBIFF8FixtureBase64)
	if err != nil {
		t.Fatalf("decode BIFF8 fixture: %v", err)
	}
	got, err := parseTagSourceByFilename(data, "tags.xls")
	if err != nil {
		t.Fatalf("xls: unexpected error: %v", err)
	}
	if len(got) != 3 {
		t.Fatalf("xls: expected 3 examples, got %d (%+v)", len(got), got)
	}
	if got[0].Content != "RAGFlow guide" || len(got[0].Tags) != 2 || got[0].Tags[0] != "RAG" || got[0].Tags[1] != "tutorial" {
		t.Errorf("xls[0] = %+v", got[0])
	}
	if got[1].Content != "LLM intro" || len(got[1].Tags) != 1 || got[1].Tags[0] != "LLM" {
		t.Errorf("xls[1] = %+v", got[1])
	}
	if got[2].Content != "solo line\ncontinued content" || len(got[2].Tags) != 2 {
		t.Errorf("xls[2] = %+v", got[2])
	}
}
